INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族扎染','工艺非遗','白族扎染是大理传统手工印染技艺，以针线扎结布料、再用植物染料浸染，形成蓝底白花的独特纹样，被誉为“布上的青花瓷”。','技艺可溯至西汉，唐宋南诏大理国已成熟；2006年列入第一批国家级非物质文化遗产，核心产地在大理喜洲镇周城村，以板蓝根等植物为染料。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('剑川木雕','工艺非遗','剑川木雕是白族传统木作雕刻工艺，以镂空、浮雕见长，广泛用于民居门窗、照壁与寺观装饰，题材多取花鸟走兽与历史故事。','源于唐代，南诏、大理国时期随佛教寺院兴建而兴盛，明清成为当地重要产业；现为国家级非物质文化遗产，北京人民大会堂云南厅木雕即出自剑川匠人之手。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族刺绣','工艺非遗','白族刺绣是白族妇女以丝线在服饰、围腰、鞋帽上绣制花草鱼虫的装饰工艺，色彩明快、针法细密，是辨识白族服饰的重要符号。','随白族服饰文化代代相传，与扎染、头饰共同构成“风花雪月”的视觉语言，是大理坝区与山区女子从小习得的女红技艺。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('鹤庆银器锻制技艺','工艺非遗','鹤庆银器是白族（及当地各民族）以纯银手工锻打、錾刻的金银饰品与器皿工艺，以新华村“小炉匠”走南闯北的手艺闻名。','制作始于唐代南诏时期，明清时新华村银匠遍及滇川藏；现为国家级非物质文化遗产，产品远销海内外。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族民居彩绘','工艺非遗','白族民居彩绘（含泥塑、彩画）是在照壁、门楼、檐口绘制山水花鸟与吉祥图案的建筑装饰工艺，使青砖白墙显出富丽色彩。','随“三坊一照壁”民居体系成熟于明清，2008年列入第二批国家级非物质文化遗产，题材常取自《三国演义》《西厢记》等故事。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族布扎','工艺非遗','白族布扎是用布料缝制、内填棉絮的生肖与神兽小玩具，造型夸张可爱，常见于端午等节令，寓意驱邪纳福。','由白族民间刺绣与玩具工艺结合而来，周城等地女子代代相传，是白族儿童节令饰物与手工艺品。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('瓦猫','工艺非遗','瓦猫是置于白族民居屋顶正脊两端的陶制瑞兽，张口昂首、形似猫虎，用于镇宅辟邪、求吉纳祥。','源于白族本主崇拜与中原脊兽文化融合，明清时期随民居兴建遍及大理，是白族建筑“镇脊”习俗的实物体现。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族甲马','工艺非遗','白族甲马（又称纸马）是白族民间木刻版画，以墨线印于彩纸，用于祭祀、祈福时焚烧或张贴，承载自然与神灵崇拜。','由唐代雕版印刷与白族本主、巫风信仰结合而来，剑川、大理一带至今保留数百种传统画样，是活态的民间版画画种。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('剑川黑陶','工艺非遗','剑川黑陶是白族传统制陶工艺，以本地陶土手工拉坯、烟熏渗碳而成，胎体乌黑光亮、古朴厚重。','黑陶制作在剑川有上千年历史，与当地稻作、饮食器皿需求相伴而生，现代恢复后成为白族手工艺代表之一。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('石钟山石窟','工艺非遗','石钟山石窟是开凿于南诏、大理国时期的佛教摩崖造像群，以剑川石雕精湛著称，被誉为“西南敦煌”。','始凿于公元9世纪，由南诏王室与白族信众历时数百年雕造，是研究南诏大理国历史与白族佛教艺术的宝库，为全国重点文物保护单位。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('三坊一照壁','建筑','三坊一照壁是白族典型民居格局，由正房、两侧厢房合围，正前立一面照壁，既围合庭院又借景采光。','随中原合院建筑与白族聚居需求在明清定型，适应当地多风、日照强的气候，是白族“粉墙画壁”民居的核心形制。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('四合五天井','建筑','四合五天井是白族富裕人家的大型合院，四栋房屋围合、四角各设小天井，主院四角加漏角天井，共“五天井”。','由三坊一照壁发展而来，多见于喜洲等商帮重镇，反映清末民初白族工商大户的家族聚居与财富象征。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族照壁题字','建筑','白族照壁是院落前的高墙，壁上常题写体现家风的词语，如杨姓“清白传家”、张姓“百忍家风”、李姓“紫气东来”、董姓“南诏宰辅”。','照壁题字源于中原门第文化与白族宗族观念结合，以壁为“门面”标示姓氏郡望与家训，是“清白传家”价值观的可见载体。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族门楼','建筑','白族门楼是民居入口的装饰性牌楼，以木雕、彩绘、泥塑层层叠叠，飞檐翘角，是整座院落最讲究的“脸面”。','门楼艺术随明清民居彩绘、木雕工艺兴盛而成熟，喜洲商帮竞筑华丽门楼以显家世，有“大理有三宝，门楼算一宝”之说。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('崇圣寺三塔','建筑','崇圣寺三塔是大理标志性建筑，主塔千寻塔高约69米，南北两小塔拱卫，矗立于苍山洱海之间，是南诏佛教鼎盛的象征。','三塔建于唐代（南诏劝丰祐时期，约公元9世纪），历千年地震不倒，1961年列为全国重点文物保护单位，也是绕三灵“佛都”所在。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族三道茶','饮食','三道茶是白族待客的最高茶礼，以“一苦、二甜、三回味”三杯茶循序敬客，隐喻先苦后甜、回味人生。','源于南诏时期（唐代《蛮书》有载），明代已成待客礼仪，白语称“绍道兆”；2014年列入第四批国家级非物质文化遗产。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('乳扇','饮食','乳扇是用鲜牛奶加酸浆熬制、拉片晾晒而成的乳制品，形似折扇，可烤、炸、炒，是大理“牛奶做成扇子卖”的奇食。','制作随大理乳畜业与白族食乳习惯兴起于元明，洱源、大理一带家家会做，是云南“十八怪”之一。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('喜洲粑粑','饮食','喜洲粑粑是喜洲古镇名点，分咸（葱花肉末）、甜（玫瑰糖）两味，外皮酥香、内里松软，有“大理披萨”之称。','由白族麦食文化与茶马古道驿站经济孕育，喜洲作为商埠自古有赶集吃粑粑之俗，至今为游客必尝小吃。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('饵块与饵丝','饮食','饵块、饵丝是大理以大米蒸捣而成的主食，饵块可烤可炒，饵丝多煮为早点，柔韧爽滑。','源于云南稻作传统，白族将糯米与粳米舂制成饵，明清已成日常主食，腾冲、大理饵丝各有流派。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('生皮','饮食','生皮（或称“海格”）是白族传统名菜，将稻草火烧猪的皮肉切生、蘸梅子辣醋而食，被称为“白族第一菜”。','为白族古老食俗，与大理养猪、火燎去毛的屠宰方式相关，是待客与节庆的厚礼，今多见于白族村落宴席。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('大理酸辣鱼','饮食','酸辣鱼是白族家宴主菜，取洱海鱼加酸木瓜（或炖梅）与辣椒、豆腐慢炖，酸辣开胃、鱼肉鲜甜。','依托洱海渔获与白族“酸辣鲜香”口味形成，婚丧节庆必备，是苍洱水域饮食文化的代表。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('雕梅','饮食','雕梅是大理蜜饯名品，在青梅上雕出花纹、去核压实后以糖渍，形如镂空菊花，香甜可口。','制作始于清代，洱源姑娘自幼学雕梅，“一张梅花俏大理”；既是茶点也是婚嫁女红才艺的象征。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族八大碗','饮食','八大碗（喜洲土八碗）是白族婚丧宴客的八道蒸炖热菜，含红肉、酥肉、千张肉、粉蒸肉等，寓意圆满丰足。','由白族节庆“办席”习俗与坝区物产组合而成，逢本主节、婚宴必摆，是白族宴饮礼仪的集中体现。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('大理蜜饯','饮食','大理蜜饯以青梅、木瓜、冬瓜等加糖熬渍而成，品种繁多、清甜不腻，是白族茶席与伴手礼的常客。','工艺随茶马古道商贸与果品加工兴起，与三道茶、雕梅同源，洱源为传统蜜饯之乡。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('“风花雪月”头饰','服饰','白族少女头饰以“风花雪月”为设计，垂穗象征下关风、花饰象征上关花、帽顶洁白象征苍山雪、弯月造型象征洱海月。','这一意象将大理四景“穿戴”于身，2017年作为白族服饰组成部分列入云南省非物质文化遗产，是识别“金花”的鲜明标志。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族金花装','服饰','金花装是白族女子盛装，以白色为尊，配红蓝丝绒领褂、绣花短围腰、蓝色宽裤与绣花鞋，头戴风花雪月帽。','由明清白族“尚白”习俗与各地绣艺融合而来，因电影《五朵金花》中“金花”形象广为人知，成为白族女性代称。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族阿鹏装','服饰','阿鹏装是白族男子传统打扮，头缠白色或蓝色包头，内穿白对襟衣、外罩黑领褂，下着宽裤，英武洒脱。','男装同样尚白，与女装同源；“阿鹏”因《五朵金花》成为白族小伙的统称，与“金花”成对称文化符号。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族扎染服饰','服饰','白族男女常以扎染布做围腰、头帕、挎包与衣衫，蓝白花纹与白底服装相映，是日常与节庆兼用的服饰元素。','扎染自周城等地进入衣饰，与“尚白”审美互补，明清已成居家必备，今为白族服饰最富辨识度的面料。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族绣花挎包','服饰','白族绣花挎包是男女皆用的日常配饰，以刺绣花卉禽鸟装饰，实用又显手艺。','挎包与白族劳作、赶集生活相伴，男子挂于肩、女子系于腰，绣样多取自山茶、蝴蝶等本土意象。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('三月街','节庆','三月街是白族最盛大的传统节日，农历三月十五至廿一在苍山中和峰下举行，集贸易、赛马、对歌、白剧于一体。','起于唐代南诏（相传纪念观音伏罗刹），原为观音庙会，1991年起定为大理白族自治州“民族节”，有“千年赶一街”之说。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('绕三灵','节庆','绕三灵是白族农闲迎神赛会，农历四月廿三至廿五，群众巡游“佛都”崇圣寺、“神都”圣源寺、“仙都”河矣城，载歌载舞。','源于南诏祈雨仪式，2006年列入第一批国家级非物质文化遗产，俗称“东方情人节”，有“绕三灵，免三灾”之谚。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('火把节','节庆','火把节白族于农历六月廿五举行，竖火把、撒松香、持小火把绕田驱虫，预祝五谷丰登、六畜兴旺。','节俗源于“火烧松明楼”传说，纪念忠贞的柏洁夫人；白族过六月廿五（彝族为六月廿四），妇女染红指甲以悼念。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('本主节','节庆','本主节是各村祭祀本境保护神“本主”的庙会，杀猪宰羊、抬神巡游，热闹往往胜过春节。','本主崇拜是白族独有信仰，“本主”可为本村英雄、自然神或历史人物，诞辰各异，故本主节日期“各村不一”。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('蝴蝶会','节庆','蝴蝶会于农历四月十五在蝴蝶泉举行，青年男女对歌相会，纪念为爱投泉的霞郎与雯姑。','会俗源于白族爱情传说，每逢泉边蝴蝶云集，渐成相恋、对歌的春日盛会，与《五朵金花》蝴蝶泉场景相映。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('石宝山歌会','节庆','石宝山歌会是剑川一带白族对歌盛会，农历七月廿七至八月初一，四方歌手云集石宝山弹弦对调、以歌觅偶。','歌会已有上千年历史，与石宝山石窟佛教活动相伴生，是白族“曲本”与情歌文化的活态展演。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('栽秧会','节庆','栽秧会是大理坝区插秧时节的农事节庆，祭秧旗、耍龙、集体栽秧并唱调子，祈愿丰收。','由白族稻作祭祀与劳动协作结合而来，把艰苦农活变为狂欢，体现“以劳定国、御灾祈丰”的本主精神。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('耍海会','节庆','耍海会（放海灯）是洱海沿岸白族庆贺渔获、祭祀龙王的节会，划龙船、对歌、放灯，热闹于夏秋。','依托洱海渔猎与龙王信仰，部分沿湖村落在农历八月初八前后举行，是苍洱水域特有的水乡庆典。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('霸王鞭','歌舞','霸王鞭是白族代表性民间舞，舞者持山竹彩棍（间串铜钱），以鞭轻击肩肘膝踝，铜钱作响、节奏明快。','相传与明清军屯、社火有关，常于绕三灵、本主节表演，可独舞也可组成“一条龙”“四梅花”队形，老少皆宜。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族调','歌舞','白族调是白族山歌小调的总称，用白语演唱，多为男女对唱的情歌与田调，旋律高亢婉转。','随白语与稻作山乡生活孕育，石宝山歌会、绕三灵是其展演舞台，是白族口头文学的载体。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('大本曲','歌舞','大本曲是白族说唱艺术，以三弦伴奏、用白语（夹汉语）演唱长篇故事，一人多角、说唱兼备。','形成于明清，受汉族弹词影响又保留白族韵味，与白剧同源，是白族韵文叙事的代表曲种。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('洞经音乐','歌舞','洞经音乐是大理流传的古老礼乐，以丝竹管弦演奏《文昌大洞仙经》等曲目，庄重典雅，多用于庙会与节庆。','由明清中原道教经乐传入云南、与白族民间音乐融合而成，大理洞经会至今在古城、喜洲演奏。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白剧','歌舞','白剧是白族唯一戏曲剧种，融吹吹腔、大本曲与白族歌舞于一体，用白语（或汉语）演唱历史与民间故事。','由吹吹腔（明中叶传入的弋阳腔支脉）与大本曲合流，1960年代定名，2008年列入国家级非物质文化遗产。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('吹吹腔','歌舞','吹吹腔是白族古老腔调戏曲，以唢呐（“吹吹”）主奏、帮腔伴唱，唱腔高亢、行当分明，是白剧的前身之一。','约明中叶由汉族戏曲随军屯传入大理，与白族语言、民俗结合，在云龙、大理一带草台演出数百年。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('本主崇拜','信仰民俗','本主崇拜是白族全民信仰，各村奉“本主”为境域保护神，神祇包罗英雄、自然神、佛道人物乃至平民。','萌于南诏前本土巫风，定型于南诏大理国，白语称本主为“武增”（本境福主），体现“兼容并蓄、护佑现世”的观念。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白语','语言','白语是白族母语，属汉藏语系藏缅语族彝语支，汉语借词极多，分大理、剑川、碧江三大方言。','随洱海土著与氐羌、汉族融合在唐宋南诏大理国时期成型，明清渐以汉字通行，聚居区仍“在家白语、对外汉语”。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白文','语言','白文是记录白语的文字，古有借用汉字的“老白文”（见于碑刻、经卷），现代有1993年列为云南正式民族文字的“新白文”（拉丁字母）。','老白文随南诏大理国汉白交融产生，存于《山花碑》等；新白文为语言普查后规范，用于双语教学与民间刊物。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('金花与阿鹏','文化符号','“金花”“阿鹏”是大理白族姑娘与小伙的代称，源自1959年电影《五朵金花》，今成大理文旅的亲和符号。','影片以三月街、蝴蝶泉为背景塑造金花与阿鹏的爱情，使白族称谓与风物走向全国。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('白族婚俗','信仰民俗','白族婚俗含提亲、订婚、迎娶三阶段，婚礼上有亲友轻“掐”新娘手臂之举，寓意“掐”来幸福吉祥。','婚仪承中原六礼又具白族特点，掐新娘、拜本主等习俗与“清白传家”家风、村社互助观念交织。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('望夫云传说','传说','望夫云是苍山玉带云中的一缕云，传说为公主所化，欲借大风吹开洱海救出被罗刹化为石骡的猎人阿龙。','传说将苍山云、洱海风人格化，是白族解释“下关风大”的著名神话，与“风花雪月”中的“风”相呼应。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
INSERT INTO symbols (name,category,description,symbol_trace,source,image_prompt,aliases,related_materials,status) VALUES ('蝴蝶泉传说','传说','蝴蝶泉传说讲白族青年霞郎与雯姑为抗封建压迫、双双投泉，化作泉边蝴蝶年年相会，故有“蝴蝶会”。','传说附会于大理蝴蝶泉奇观（农历四月蝴蝶群集），成为白族追求自由爱情的代言，亦为《五朵金花》取景意象。','白族特色50样清单(内容组)','','[]','[]','published') ON DUPLICATE KEY UPDATE category=VALUES(category), description=VALUES(description), symbol_trace=VALUES(symbol_trace), source=VALUES(source);
